 31 | </head>
 32 | <body>
 33 | <div id="toolbar">
 34 |   <button id="btn-table" disabled>Table <span class="hint">[T]</span></button>
 35 |   <button id="btn-couch">Sofa <span class="hint">[C]</span></button>
 36 |   <button id="btn-lsofa">L-Sofa <span class="hint">[L]</span></button>
 37 |   <button id="btn-chair">Chair <span class="hint">[H]</span></button>
 38 |   <button id="btn-rug">Rug <span class="hint">[P]</span></button>
 39 |   <button id="btn-delete" disabled>Delete <span class="hint">[D]</span></button>
 40 |   <button id="btn-chaos">Chaos</button>
 41 |   <div class="sep"></div>
 42 |   <span class="face-label">Face:</span>
 43 |   <button id="face-top"    class="active">Top</button>
 44 |   <button id="face-bottom">Bottom</button>
 45 |   <button id="face-front"> Front</button>
 46 |   <button id="face-back">  Back</button>
 47 |   <button id="face-left">  Left</button>
 48 |   <button id="face-right"> Right</button>
 49 | </div>
 50 | <div id="canvas-wrap">
 51 |   <canvas id="three-canvas"></canvas>
 52 |   <div id="face-indicator">Face: TOP</div>
 53 |   <div id="hud">Drag floor=select &middot; Arrows=move &middot; [W/S]=float &middot; [Q]=CCW &middot; [E/R]=CW &middot; Right-drag/scroll=orbit &middot; [D]=delete &middot; [Esc]=cancel</div>
 54 |   <div id="rug-counter">0/16 cells — Enter=place Esc=cancel</div>
 55 | </div>
 56 | <div id="gameover-overlay">
 57 |   <h1>GAME OVER</h1>
 58 |   <p id="gameover-msg">A piece sat in conflict too long.</p>
 59 |   <button onclick="location.reload()">Try Again</button>
 60 | </div>
 61 | <script>
 62 | 
 63 | // ═══════════════════════════════════════════════════════════════
 64 | //  Room Packer 3D  —  64×64×64 cube, 6 placeable faces
 65 | // ═══════════════════════════════════════════════════════════════
 66 | const SIZE=64, CELL=1.0;
 67 | const H_TABLE=1.0,H_COUCH=2.0,H_LSOFA=2.0,H_CHAIR=2.0,H_RUG=0.08;
 68 | 
 69 | // ── Three.js setup ────────────────────────────────────────────
 70 | const canvas=document.getElementById('three-canvas');
 71 | const wrap  =document.getElementById('canvas-wrap');
 72 | const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
 73 | renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
 74 | renderer.shadowMap.enabled=true;
 75 | renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 76 | renderer.setClearColor(0x0d0d1a);
 77 | 
 78 | const VIEW=SIZE*CELL*0.75;
 79 | const camera=new THREE.OrthographicCamera(-VIEW,VIEW,VIEW,-VIEW,-1000,1000);
 80 | const scene=new THREE.Scene();
 81 | scene.fog=new THREE.FogExp2(0x0d0d1a,0.006);
 82 | 
 83 | scene.add(new THREE.AmbientLight(0xffffff,0.55));
 84 | const sun=new THREE.DirectionalLight(0xfff8e7,0.85);
 85 | sun.position.set(80,120,80);sun.castShadow=true;
 86 | sun.shadow.mapSize.set(2048,2048);
 87 | sun.shadow.camera.left=-100;sun.shadow.camera.right=100;
 88 | sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;
 89 | sun.shadow.camera.near=1;sun.shadow.camera.far=500;
 90 | scene.add(sun);
 91 | scene.add(Object.assign(new THREE.DirectionalLight(0xc8d8ff,0.2),{position:new THREE.Vector3(-40,40,-20)}));
 92 | 
 93 | // ── Face definitions ──────────────────────────────────────────
 94 | // Each face of the 64³ cube has:
 95 | //   normal  : outward-facing direction (unit vec3)
 96 | //   origin  : world-space corner of the face (where u=0,v=0)
 97 | //   uAxis   : world-space direction of "column" axis on the face
 98 | //   vAxis   : world-space direction of "row" axis on the face
 99 | //   offset  : distance from centre to push pieces off the face surface
100 | //
101 | // The cube occupies [0,SIZE]³ in world space.
102 | const HALF=SIZE/2;
103 | const FACES={
104 |   top:   {name:'TOP',    normal:new THREE.Vector3( 0, 1, 0), origin:new THREE.Vector3(0,SIZE,0),   uAxis:new THREE.Vector3(1,0,0), vAxis:new THREE.Vector3(0,0,1)},
105 |   bottom:{name:'BOTTOM', normal:new THREE.Vector3( 0,-1, 0), origin:new THREE.Vector3(0,0,SIZE),   uAxis:new THREE.Vector3(1,0,0), vAxis:new THREE.Vector3(0,0,-1)},
106 |   front: {name:'FRONT',  normal:new THREE.Vector3( 0, 0, 1), origin:new THREE.Vector3(0,SIZE,SIZE),uAxis:new THREE.Vector3(1,0,0), vAxis:new THREE.Vector3(0,-1,0)},
107 |   back:  {name:'BACK',   normal:new THREE.Vector3( 0, 0,-1), origin:new THREE.Vector3(SIZE,SIZE,0),uAxis:new THREE.Vector3(-1,0,0),vAxis:new THREE.Vector3(0,-1,0)},
108 |   left:  {name:'LEFT',   normal:new THREE.Vector3(-1, 0, 0), origin:new THREE.Vector3(0,SIZE,SIZE),uAxis:new THREE.Vector3(0,0,-1),vAxis:new THREE.Vector3(0,-1,0)},
109 |   right: {name:'RIGHT',  normal:new THREE.Vector3( 1, 0, 0), origin:new THREE.Vector3(SIZE,SIZE,0),uAxis:new THREE.Vector3(0,0,1), vAxis:new THREE.Vector3(0,-1,0)},
110 | };
111 | 
112 | // Convert face (u,v) grid coords to world position (top-left of cell)
113 | function faceUVtoWorld(faceKey,u,v){
114 |   const f=FACES[faceKey];
115 |   return f.origin.clone()
116 |     .addScaledVector(f.uAxis,u*CELL)
117 |     .addScaledVector(f.vAxis,v*CELL);
118 | }
119 | // Center of a cell on a face
120 | function faceCellCenter(faceKey,u,v,height){
121 |   const f=FACES[faceKey];
122 |   return f.origin.clone()
123 |     .addScaledVector(f.uAxis,(u+0.5)*CELL)
124 |     .addScaledVector(f.vAxis,(v+0.5)*CELL)
125 |     .addScaledVector(f.normal,height/2);
126 | }
127 | 
128 | // ── Cube wireframe ────────────────────────────────────────────
129 | const cubeEdges=new THREE.LineSegments(
130 |   new THREE.EdgesGeometry(new THREE.BoxGeometry(SIZE,SIZE,SIZE)),
131 |   new THREE.LineBasicMaterial({color:0x334466,transparent:true,opacity:0.5})
132 | );
133 | cubeEdges.position.set(HALF,HALF,HALF);
134 | scene.add(cubeEdges);
135 | 
136 | // ── Floor grids per face ──────────────────────────────────────
137 | // We render a tile grid on each of the 6 faces.
138 | const faceGroups={};
139 | const tileGeoF=new THREE.BoxGeometry(CELL,0.06,CELL);
140 | const matTileL=new THREE.MeshLambertMaterial({color:0xf0d9b5});
141 | const matTileD=new THREE.MeshLambertMaterial({color:0xb58863});
142 | 
143 | for(const [faceKey,face] of Object.entries(FACES)){
144 |   const group=new THREE.Group();
145 |   for(let v=0;v<SIZE;v++){
146 |     for(let u=0;u<SIZE;u++){
147 |       // Build a thin tile oriented to the face
148 |       const geo=new THREE.BoxGeometry(CELL*0.98,0.05,CELL*0.98);
149 |       const mat=(u+v)%2===0?matTileL:matTileD;
150 |       const m=new THREE.Mesh(geo,mat);
151 |       m.receiveShadow=true;
152 |       // Position at cell centre on the face surface
153 |       const centre=faceCellCenter(faceKey,u,v,0);
154 |       // Push slightly outward so it sits on the face
155 |       centre.addScaledVector(face.normal,0.03);
156 |       m.position.copy(centre);
157 |       // Rotate tile to align with the face normal
158 |       m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),face.normal);
159 |       m.userData={isTile:true,face:faceKey,u,v};
160 |       group.add(m);
161 |     }
162 |   }
163 |   faceGroups[faceKey]=group;
164 |   scene.add(group);
165 | }
166 | 
167 | // ── Active face state ─────────────────────────────────────────
168 | let activeFace='top';
169 | const faceIndicator=document.getElementById('face-indicator');
170 | 
171 | function setActiveFace(key){
172 |   activeFace=key;
173 |   faceIndicator.textContent='Face: '+FACES[key].name;
174 |   // Dim inactive face grids, brighten active
175 |   for(const [k,g] of Object.entries(faceGroups)){
176 |     g.traverse(ch=>{
177 |       if(ch.isMesh&&ch.material){
178 |         ch.material=k===key?
179 |           (ch.userData&&(ch.userData.u+ch.userData.v)%2===0?matTileL:matTileD):
180 |           (ch.userData&&(ch.userData.u+ch.userData.v)%2===0?matTileLDim:matTileDDim);
181 |       }
182 |     });
183 |   }
184 |   // Update face button active styles
185 |   for(const k of Object.keys(FACES)){
186 |     document.getElementById('face-'+k).classList.toggle('active',k===key);
187 |   }
188 | }
189 | 
190 | // Dimmed tile materials
191 | const matTileLDim=new THREE.MeshLambertMaterial({color:0x887766,transparent:true,opacity:0.3});
192 | const matTileDDim=new THREE.MeshLambertMaterial({color:0x665544,transparent:true,opacity:0.3});
193 | 
194 | // Init face visuals (dim all except top)
195 | for(const [faceKey,group] of Object.entries(faceGroups)){
196 |   group.traverse(ch=>{
197 |     if(ch.isMesh&&ch.userData&&ch.userData.isTile){
198 |       const isActive=faceKey===activeFace;
199 |       ch.material=isActive?
200 |         ((ch.userData.u+ch.userData.v)%2===0?matTileL:matTileD):
201 |         ((ch.userData.u+ch.userData.v)%2===0?matTileLDim:matTileDDim);
202 |     }
203 |   });
204 | }
205 | 
206 | // ── Per-face grid occupancy ───────────────────────────────────
207 | // gridOcc[face][v][u] = [pieceId, ...]
208 | const gridOcc={};
209 | for(const key of Object.keys(FACES)){
210 |   gridOcc[key]=[];
211 |   for(let v=0;v<SIZE;v++){gridOcc[key][v]=[];for(let u=0;u<SIZE;u++)gridOcc[key][v][u]=[];}
212 | }
213 | 
214 | function stampRect(face,id,uMin,vMin,uMax,vMax){
215 |   for(let v=vMin;v<=vMax;v++)for(let u=uMin;u<=uMax;u++)
216 |     if(!gridOcc[face][v][u].includes(id))gridOcc[face][v][u].push(id);
217 | }
218 | function eraseRect(face,id,uMin,vMin,uMax,vMax){
219 |   for(let v=vMin;v<=vMax;v++)for(let u=uMin;u<=uMax;u++)
220 |     gridOcc[face][v][u]=gridOcc[face][v][u].filter(x=>x!==id);
221 | }
222 | function stampCells(face,id,cells){
223 |   for(const{u,v}of cells)if(!gridOcc[face][v][u].includes(id))gridOcc[face][v][u].push(id);
224 | }
225 | function eraseCells(face,id,cells){
226 |   for(const{u,v}of cells)gridOcc[face][v][u]=gridOcc[face][v][u].filter(x=>x!==id);
227 | }
228 | function hasConflict(face,uMin,vMin,uMax,vMax,ignoreId=null){
229 |   for(let v=vMin;v<=vMax;v++)for(let u=uMin;u<=uMax;u++)
230 |     for(const id of gridOcc[face][v][u])if(id!==ignoreId)return true;
231 |   return false;
232 | }
233 | function hasConflictCells(face,cells,ignoreId=null){
234 |   for(const{u,v}of cells){
235 |     if(u<0||v<0||u>=SIZE||v>=SIZE)return true;
236 |     for(const id of gridOcc[face][v][u])if(id!==ignoreId)return true;
237 |   }
238 |   return false;
239 | }
240 | 
241 | // ── Piece state ───────────────────────────────────────────────
242 | let pieceCounter=0;
243 | const pieces=[];
244 | let selectedPiece=null;
245 | let couchMode=false,ghostOrientation='h';
246 | let chairMode=false;
247 | let lsofaMode=false,lsofaVariant='se';
248 | let lsofaGhostLenA=3,lsofaGhostLenB=3;
249 | let rugMode=false,rugCount=0,rugPaintCells=new Set();
250 | let gameOver=false;
251 | let selDragging=false,selStart=null,selRect=null,selMesh=null;
252 | let draggingPiece=null,dragOffU=0,dragOffV=0;
253 | 
254 | // ── Ghost / selection mesh helpers ───────────────────────────
255 | let ghostMeshes=[];
256 | function clearGhosts(){for(const m of ghostMeshes)scene.remove(m);ghostMeshes=[];}
257 | 
258 | function makeFaceMesh(face,uMin,vMin,uMax,vMax,height,color,opacity,normalOff=0){
259 |   const f=FACES[face];
260 |   const cols=uMax-uMin+1,rows=vMax-vMin+1;
261 |   // Create a box oriented to the face
262 |   const geo=new THREE.BoxGeometry(cols*CELL,height,rows*CELL);
263 |   const mat=new THREE.MeshLambertMaterial({color,transparent:opacity<1,opacity:opacity??1});
264 |   const mesh=new THREE.Mesh(geo,mat);
265 |   mesh.castShadow=mesh.receiveShadow=true;
266 |   // Edge lines
267 |   const eMat=new THREE.LineBasicMaterial({color:0x000000,transparent:true,opacity:0.3});
268 |   mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo),eMat));
269 |   // Position: centre of the rect, pushed out by height/2 + normalOff from face
270 |   const centre=f.origin.clone()
271 |     .addScaledVector(f.uAxis,(uMin+cols/2)*CELL)
272 |     .addScaledVector(f.vAxis,(vMin+rows/2)*CELL)
273 |     .addScaledVector(f.normal,(normalOff||0)+height/2);
274 |   mesh.position.copy(centre);
275 |   // Align box axes to face
276 |   const q=new THREE.Quaternion();
277 |   const up=new THREE.Vector3(0,1,0);
278 |   // We need: mesh local Y → face normal, mesh local X → face uAxis, mesh local Z → face vAxis
279 |   // Build rotation matrix from axes
280 |   const xAxis=f.uAxis.clone();
281 |   const yAxis=f.normal.clone();
282 |   const zAxis=f.vAxis.clone();
283 |   const m4=new THREE.Matrix4().makeBasis(xAxis,yAxis,zAxis);
284 |   mesh.setRotationFromMatrix(m4);
285 |   return mesh;
286 | }
287 | 
288 | function addGhostRect(face,uMin,vMin,uMax,vMax,height,color,conflict){
289 |   const mesh=makeFaceMesh(face,uMin,vMin,uMax,vMax,height,conflict?0xff4444:color,0.42);
290 |   scene.add(mesh);ghostMeshes.push(mesh);
291 | }
292 | 
293 | function addGhostCells(face,cells,height,color,conflict){
294 |   const f=FACES[face];
295 |   const geo=new THREE.BoxGeometry(CELL*0.94,height,CELL*0.94);
296 |   const xAxis=f.uAxis.clone(),yAxis=f.normal.clone(),zAxis=f.vAxis.clone();
297 |   const m4=new THREE.Matrix4().makeBasis(xAxis,yAxis,zAxis);
298 |   const quat=new THREE.Quaternion().setFromRotationMatrix(m4);
299 |   for(const{u,v}of cells){
300 |     const mat=new THREE.MeshBasicMaterial({color:conflict?0xff4444:color,transparent:true,opacity:0.45});
301 |     const m=new THREE.Mesh(geo,mat);
302 |     const centre=f.origin.clone()
303 |       .addScaledVector(f.uAxis,(u+0.5)*CELL)
304 |       .addScaledVector(f.vAxis,(v+0.5)*CELL)
305 |       .addScaledVector(f.normal,height/2);
306 |     m.position.copy(centre);m.quaternion.copy(quat);
307 |     scene.add(m);ghostMeshes.push(m);
308 |   }
309 | }
310 | 
311 | // Selection rect (table placement)
312 | function setSelRectMesh(face,uMin,vMin,uMax,vMax,conflict){
313 |   if(selMesh){scene.remove(selMesh);selMesh=null;}
314 |   selMesh=makeFaceMesh(face,uMin,vMin,uMax,vMax,0.12,conflict?0xe05555:0x7fc97f,0.5);
315 |   scene.add(selMesh);
316 | }
317 | function clearSelRectMesh(){if(selMesh){scene.remove(selMesh);selMesh=null;}}
318 | 
319 | // Selection highlight halo
320 | let selHighlight=null;
321 | function updateSelHighlight(p){
322 |   if(selHighlight){scene.remove(selHighlight);selHighlight=null;}
323 |   if(!p)return;
324 |   const cols=p.uMax-p.uMin+1,rows=p.vMax-p.vMin+1;
325 |   selHighlight=makeFaceMesh(p.face,p.uMin-0.1,p.vMin-0.1,p.uMax+0.1,p.vMax+0.1,0.06,0xffffff,0.3);
326 |   // Push halo slightly higher than the piece
327 |   selHighlight.position.addScaledVector(FACES[p.face].normal,(p.floatDepth||0)*CELL+p.height+0.07);
328 |   scene.add(selHighlight);
329 | }
330 | 
331 | // Colour palettes
332 | const TABLE_COLORS=[0xe07b54,0x5b9bd5,0xe8a838,0x8e6bbf,0x4caf8a,0xd95f8a,0x6ab04c,0xc0392b];
333 | const COUCH_COLORS=[0xb86fc4,0x7a6bc4,0x4fa8d0,0x4db89e,0xd4a03e,0xd06060,0x6ba05a,0x9a8060];
334 | const RUG_COLORS  =[0xe07b54,0x5b9bd5,0x8e6bbf,0x4caf8a,0xd95f8a,0xe8a838,0x6ab04c,0xc0392b];
335 | const CHAIR_COLOR =0x4ecdc4;
336 | 
337 | // Conflict colour
338 | function setMeshColor(obj,hex){
339 |   obj.traverse(ch=>{if(ch.isMesh&&ch.material&&ch.material.color&&!ch.material.wireframe)ch.material.color.setHex(hex);});
340 | }
341 | function refreshPieceColor(p){
342 |   const cf=p.cells?hasConflictCells(p.face,p.cells,p.id):hasConflict(p.face,p.uMin,p.vMin,p.uMax,p.vMax,p.id);
343 |   setMeshColor(p.mesh,cf?0xe05555:p.color);
344 | }
345 | function refreshAllColors(){for(const p of pieces)refreshPieceColor(p);}
346 | 
347 | // ── Place pieces ──────────────────────────────────────────────
348 | const TABLE_MIN=2,TABLE_MAX=24;
349 | 
350 | function placeTable(face,uMin,vMin,uMax,vMax){
351 |   const cols=uMax-uMin+1,rows=vMax-vMin+1;
352 |   if(cols<TABLE_MIN||rows<TABLE_MIN||cols>TABLE_MAX||rows>TABLE_MAX)return null;
353 |   const id=pieceCounter++;
354 |   const color=TABLE_COLORS[id%TABLE_COLORS.length];
355 |   const mesh=makeFaceMesh(face,uMin,vMin,uMax,vMax,H_TABLE,color,1);
356 |   scene.add(mesh);mesh.userData.pieceId=id;
357 |   const p={id,type:'table',face,uMin,vMin,uMax,vMax,color,label:'Table '+(id+1),mesh,height:H_TABLE,floatDepth:0};
358 |   pieces.push(p);stampRect(face,id,uMin,vMin,uMax,vMax);return p;
359 | }
360 | 
361 | const COUCH_W=2,COUCH_L=4;
362 | function couchDims(u,v){
363 |   if(ghostOrientation==='h')return{uMin:u,vMin:v,uMax:Math.min(u+COUCH_L-1,SIZE-1),vMax:Math.min(v+COUCH_W-1,SIZE-1)};
364 |   return{uMin:u,vMin:v,uMax:Math.min(u+COUCH_W-1,SIZE-1),vMax:Math.min(v+COUCH_L-1,SIZE-1)};
365 | }
366 | function placeCouch(face,uMin,vMin,uMax,vMax,orientation){
367 |   const id=pieceCounter++;
368 |   const color=COUCH_COLORS[pieces.filter(p=>p.type==='couch').length%COUCH_COLORS.length];
369 |   const mesh=makeFaceMesh(face,uMin,vMin,uMax,vMax,H_COUCH,color,1);
370 |   scene.add(mesh);mesh.userData.pieceId=id;
371 |   const p={id,type:'couch',face,uMin,vMin,uMax,vMax,color,label:'Sofa '+(id+1),mesh,height:H_COUCH,orientation,floatDepth:0};
372 |   pieces.push(p);stampRect(face,id,uMin,vMin,uMax,vMax);return p;
373 | }
374 | 
375 | function placeChair(face,u,v){
376 |   const id=pieceCounter++;
377 |   const f=FACES[face];
378 |   const geo=new THREE.CylinderGeometry(0.36,0.36,H_CHAIR,20);
379 |   const mat=new THREE.MeshLambertMaterial({color:CHAIR_COLOR});
380 |   const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=true;
381 |   const centre=f.origin.clone()
382 |     .addScaledVector(f.uAxis,(u+0.5)*CELL)
383 |     .addScaledVector(f.vAxis,(v+0.5)*CELL)
384 |     .addScaledVector(f.normal,H_CHAIR/2);
385 |   mesh.position.copy(centre);
