393 | function lsofaCells(aU,aV,lenA,lenB,variant){
394 |   const set=new Set();
395 |   const add=(u1,v1,u2,v2)=>{for(let v=v1;v<=v2;v++)for(let u=u1;u<=u2;u++)set.add(u+','+v);};
396 |   if(variant==='se'){add(aU,aV,aU+lenA-1,aV+1);add(aU,aV,aU+1,aV+lenB-1);}
397 |   else if(variant==='sw'){add(aU-lenA+1,aV,aU,aV+1);add(aU-1,aV,aU,aV+lenB-1);}
398 |   else if(variant==='ne'){add(aU,aV-1,aU+lenA-1,aV);add(aU,aV-lenB+1,aU+1,aV);}
399 |   else{add(aU-lenA+1,aV-1,aU,aV);add(aU-1,aV-lenB+1,aU,aV);}
400 |   return[...set].map(k=>{const[u,v]=k.split(',').map(Number);return{u,v};});
401 | }
402 | function bboxOf(cells){
403 |   let uMin=Infinity,vMin=Infinity,uMax=-Infinity,vMax=-Infinity;
404 |   for(const{u,v}of cells){uMin=Math.min(uMin,u);vMin=Math.min(vMin,v);uMax=Math.max(uMax,u);vMax=Math.max(vMax,v);}
405 |   return{uMin,vMin,uMax,vMax};
406 | }
