412 |   const q=new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(xA,yA,zA));
413 |   const seatH=height*0.6,backH=height*0.4;
414 |   const seatGeo=new THREE.BoxGeometry(CELL*0.95,seatH,CELL*0.95);
415 |   const backGeo=new THREE.BoxGeometry(CELL*0.95,backH,CELL*0.22);
416 |   const matColor=new THREE.Color(color);
417 |   const mat=new THREE.MeshLambertMaterial({color,emissive:matColor.clone().multiplyScalar(0.18)});
418 |   const backMat=new THREE.MeshLambertMaterial({color:matColor.clone().lerp(new THREE.Color(0xffffff),0.18),emissive:matColor.clone().multiplyScalar(0.25)});
419 |   for(const{u,v}of cellArr){
420 |     const base=f.origin.clone()
421 |       .addScaledVector(f.uAxis,(u+0.5)*CELL)
422 |       .addScaledVector(f.vAxis,(v+0.5)*CELL);
423 |     const seat=new THREE.Mesh(seatGeo,mat);seat.castShadow=true;
424 |     seat.position.copy(base.clone().addScaledVector(f.normal,normalOff+seatH/2));
425 |     seat.quaternion.copy(q);group.add(seat);
426 |     const back=new THREE.Mesh(backGeo,backMat);back.castShadow=true;
427 |     back.position.copy(base.clone()
428 |       .addScaledVector(f.normal,normalOff+seatH+backH/2)
