396 |   if(variant==='se'){add(aU,aV,aU+lenA-1,aV+1);add(aU,aV,aU+1,aV+lenB-1);}
397 |   else if(variant==='sw'){add(aU-lenA+1,aV,aU,aV+1);add(aU-1,aV,aU,aV+lenB-1);}
398 |   else if(variant==='ne'){add(aU,aV-1,aU+lenA-1,aV);add(aU,aV-lenB+1,aU+1,aV);}
399 |   else{add(aU-lenA+1,aV-1,aU,aV);add(aU-1,aV-lenB+1,aU,aV);}
400 |   return[...set].map(k=>{const[u,v]=k.split(',').map(Number);return{u,v};});
401 | }
