function rebuildMesh(p){
  scene.remove(p.mesh);
  const op=p.opacity??1;
  if(p.type==='table'||p.type==='couch'){
    p.mesh=makeFaceMesh(p.face,p.uMin,p.vMin,p.uMax,p.vMax,p.height,p.color,op,(p.floatDepth||0)*CELL);
    scene.add(p.mesh);p.mesh.userData.pieceId=p.id;
  }else if(p.type==='chair'){
    // rebuild cylinder
    const f=FACES[p.face];
    const geo=new THREE.CylinderGeometry(0.36,0.36,p.height,20);
    const mat=new THREE.MeshLambertMaterial({color:p.color,transparent:op<1,opacity:op});
    const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=true;
    const ctr=f.origin.clone().addScaledVector(f.uAxis,(p.uMin+0.5)*CELL).addScaledVector(f.vAxis,(p.vMin+0.5)*CELL).addScaledVector(f.normal,(p.floatDepth||0)*CELL+p.height/2);
    mesh.position.copy(ctr);
    mesh.setRotationFromMatrix(new THREE.Matrix4().makeBasis(f.uAxis.clone(),f.normal.clone(),f.vAxis.clone()));
    mesh.userData.pieceId=p.id;scene.add(mesh);p.mesh=mesh;
  }else{
    const f=FACES[p.face];
    if(p.type==='lsofa'){
      const group=buildLsofaMesh(p.face,p.cells,p.color,p.height,(p.floatDepth||0)*CELL,op);
      scene.add(group);group.userData.pieceId=p.id;p.mesh=group;
    }else{
      const isRug=p.type==='rug';
      const group=new THREE.Group();
      const geo=new THREE.BoxGeometry(isRug?CELL*0.9:CELL*0.95,p.height,isRug?CELL*0.9:CELL*0.95);
      const mat=new THREE.MeshLambertMaterial({color:p.color,transparent:op<1,opacity:op});
      const q=new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(f.uAxis.clone(),f.normal.clone(),f.vAxis.clone()));
      for(const{u,v}of p.cells){
        const m=new THREE.Mesh(geo,mat);m.castShadow=true;
        const ctr=f.origin.clone().addScaledVector(f.uAxis,(u+0.5)*CELL).addScaledVector(f.vAxis,(v+0.5)*CELL).addScaledVector(f.normal,(p.floatDepth||0)*CELL+p.height/2);
        m.position.copy(ctr);m.quaternion.copy(q);group.add(m);
      }
      scene.add(group);group.userData.pieceId=p.id;p.mesh=group;
    }
  }
  refreshPieceColor(p);
}

