#toolbar{display:flex;gap:8px;align-items:center;padding:8px 14px;background:rgba(0,0,0,.55);width:100%;flex-wrap:wrap;z-index:10}
#toolbar button{background:#2e4a7a;color:#fff;border:2px solid #4a7abf;border-radius:6px;padding:6px 13px;font-size:12px;cursor:pointer;transition:background .15s,border-color .15s}
#toolbar button:hover{background:#3a5d99;border-color:#6a9acf}
#toolbar button:disabled{opacity:.35;cursor:not-allowed}
#toolbar button.active{background:#5a3a8a;border-color:#9a6acf}
#toolbar .hint{color:#aac;font-size:10px}
#toolbar .sep{width:1px;height:28px;background:rgba(255,255,255,.15);margin:0 4px}
#toolbar .face-label{color:#ffd;font-size:11px;font-weight:bold;letter-spacing:.5px}
#opacity-group{display:flex;align-items:center;gap:6px}
#opacity-group label{color:#ffd;font-size:11px;font-weight:bold;white-space:nowrap}
#opacity-slider{width:90px;accent-color:#9a6acf;cursor:pointer}
#opacity-slider:disabled{opacity:.35;cursor:not-allowed}
#opacity-val{color:#aac;font-size:11px;min-width:30px}
#canvas-wrap{position:relative;flex:1;width:100%;height:calc(100vh - 52px)}
#three-canvas{display:block;width:100%;height:100%}
#hud{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);color:#aac;font-size:11px;pointer-events:none;background:rgba(0,0,0,.5);padding:5px 12px;border-radius:6px;white-space:nowrap}
#rug-counter{position:absolute;bottom:44px;left:50%;transform:translateX(-50%);color:#ffd;font-size:12px;pointer-events:none;background:rgba(0,0,0,.65);padding:4px 12px;border-radius:6px;display:none}
#rug-counter.at-limit{color:#f55}
#face-indicator{position:absolute;top:10px;right:14px;color:#ffd;font-size:13px;font-weight:bold;pointer-events:none;background:rgba(0,0,0,.55);padding:5px 12px;border-radius:6px}
#gameover-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.82);z-index:100;flex-direction:column;align-items:center;justify-content:center;gap:18px;color:#fff}

// Conflict colour
function setMeshColor(obj,hex){
  obj.traverse(ch=>{if(ch.isMesh&&ch.material&&ch.material.color&&!ch.material.wireframe)ch.material.color.setHex(hex);});
}
function setMeshOpacity(obj,opacity){
  obj.traverse(ch=>{
    if(ch.isMesh&&ch.material&&!ch.material.wireframe){
      ch.material.transparent=opacity<1;
      ch.material.opacity=opacity;
      ch.material.needsUpdate=true;
    }
  });
}
function refreshPieceColor(p){
  const cf=p.cells?hasConflictCells(p.face,p.cells,p.id):hasConflict(p.face,p.uMin,p.vMin,p.uMax,p.vMax,p.id);
  setMeshColor(p.mesh,cf?0xe05555:p.color);
  setMeshOpacity(p.mesh,p.opacity??1);
}
function refreshAllColors(){for(const p of pieces)refreshPieceColor(p);}

