function makeFaceMesh(face,uMin,vMin,uMax,vMax,height,color,opacity,normalOff=0){
  const f=FACES[face];
  const cols=uMax-uMin+1,rows=vMax-vMin+1;
  // Create a box oriented to the face
  const geo=new THREE.BoxGeometry(cols*CELL,height,rows*CELL);
  const mat=new THREE.MeshLambertMaterial({color,transparent:opacity<1,opacity:opacity??1});
  const mesh=new THREE.Mesh(geo,mat);
  mesh.castShadow=mesh.receiveShadow=true;
  // Edge lines
  const eMat=new THREE.LineBasicMaterial({color:0x000000,transparent:true,opacity:0.3});
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo),eMat));
  // Position: centre of the rect, pushed out by height/2 + normalOff from face
  const centre=f.origin.clone()
    .addScaledVector(f.uAxis,(uMin+cols/2)*CELL)
    .addScaledVector(f.vAxis,(vMin+rows/2)*CELL)
    .addScaledVector(f.normal,(normalOff||0)+height/2);
  mesh.position.copy(centre);
  // Align box axes to face
  const q=new THREE.Quaternion();
  const up=new THREE.Vector3(0,1,0);
  // We need: mesh local Y → face normal, mesh local X → face uAxis, mesh local Z → face vAxis
  // Build rotation matrix from axes
  const xAxis=f.uAxis.clone();
  const yAxis=f.normal.clone();
  const zAxis=f.vAxis.clone();
  const m4=new THREE.Matrix4().makeBasis(xAxis,yAxis,zAxis);
  mesh.setRotationFromMatrix(m4);
  return mesh;
}

function addGhostRect(face,uMin,vMin,uMax,vMax,height,color,conflict){
  const mesh=makeFaceMesh(face,uMin,vMin,uMax,vMax,height,conflict?0xff4444:color,0.42);
  scene.add(mesh);ghostMeshes.push(mesh);
}

function addGhostCells(face,cells,height,color,conflict){
  const f=FACES[face];
  const geo=new THREE.BoxGeometry(CELL*0.94,height,CELL*0.94);
  const xAxis=f.uAxis.clone(),yAxis=f.normal.clone(),zAxis=f.vAxis.clone();
  const m4=new THREE.Matrix4().makeBasis(xAxis,yAxis,zAxis);
  const quat=new THREE.Quaternion().setFromRotationMatrix(m4);
  for(const{u,v}of cells){
    const mat=new THREE.MeshBasicMaterial({color:conflict?0xff4444:color,transparent:true,opacity:0.45});
    const m=new THREE.Mesh(geo,mat);
    const centre=f.origin.clone()
      .addScaledVector(f.uAxis,(u+0.5)*CELL)
      .addScaledVector(f.vAxis,(v+0.5)*CELL)
      .addScaledVector(f.normal,height/2);
    m.position.copy(centre);m.quaternion.copy(quat);
    scene.add(m);ghostMeshes.push(m);
  }
}

