  scene.add(selMesh);
}
function clearSelRectMesh(){if(selMesh){scene.remove(selMesh);selMesh=null;}}

// Selection highlight halo
let selHighlight=null;
function updateSelHighlight(p){
  if(selHighlight){scene.remove(selHighlight);selHighlight=null;}
  if(!p)return;
  const cols=p.uMax-p.uMin+1,rows=p.vMax-p.vMin+1;
  selHighlight=makeFaceMesh(p.face,p.uMin-0.1,p.vMin-0.1,p.uMax+0.1,p.vMax+0.1,0.06,0xffffff,0.3);
  // Push halo slightly higher than the piece
  selHighlight.position.addScaledVector(FACES[p.face].normal,(p.floatDepth||0)*CELL+p.height+0.07);
  scene.add(selHighlight);
}

