function placeChair(face,u,v){
  const id=pieceCounter++;
  const f=FACES[face];
  const geo=new THREE.CylinderGeometry(0.36,0.36,H_CHAIR,20);
  const mat=new THREE.MeshLambertMaterial({color:CHAIR_COLOR});
  const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=true;
  const centre=f.origin.clone()
    .addScaledVector(f.uAxis,(u+0.5)*CELL)
    .addScaledVector(f.vAxis,(v+0.5)*CELL)
    .addScaledVector(f.normal,H_CHAIR/2);
  mesh.position.copy(centre);
  const xA=f.uAxis.clone(),yA=f.normal.clone(),zA=f.vAxis.clone();
  mesh.setRotationFromMatrix(new THREE.Matrix4().makeBasis(xA,yA,zA));
  mesh.userData.pieceId=id;scene.add(mesh);
  const p={id,type:'chair',face,uMin:u,vMin:v,uMax:u,vMax:v,color:CHAIR_COLOR,label:'Chair '+(id+1),mesh,height:H_CHAIR,floatDepth:0,opacity:1};
  pieces.push(p);stampRect(face,id,u,v,u,v);return p;
}

function lsofaCells(aU,aV,lenA,lenB,variant){
  const set=new Set();
  const add=(u1,v1,u2,v2)=>{for(let v=v1;v<=v2;v++)for(let u=u1;u<=u2;u++)set.add(u+','+v);};
  if(variant==='se'){add(aU,aV,aU+lenA-1,aV+1);add(aU,aV,aU+1,aV+lenB-1);}
  else if(variant==='sw'){add(aU-lenA+1,aV,aU,aV+1);add(aU-1,aV,aU,aV+lenB-1);}
  else if(variant==='ne'){add(aU,aV-1,aU+lenA-1,aV);add(aU,aV-lenB+1,aU+1,aV);}
  else{add(aU-lenA+1,aV-1,aU,aV);add(aU-1,aV-lenB+1,aU,aV);}
  return[...set].map(k=>{const[u,v]=k.split(',').map(Number);return{u,v};});
}
function bboxOf(cells){
  let uMin=Infinity,vMin=Infinity,uMax=-Infinity,vMax=-Infinity;
  for(const{u,v}of cells){uMin=Math.min(uMin,u);vMin=Math.min(vMin,v);uMax=Math.max(uMax,u);vMax=Math.max(vMax,v);}
  return{uMin,vMin,uMax,vMax};
}

