  const backMat=new THREE.MeshLambertMaterial({color:matColor.clone().lerp(new THREE.Color(0xffffff),0.18),emissive:matColor.clone().multiplyScalar(0.25),transparent:opacity<1,opacity});
  for(const{u,v}of cellArr){
    const base=f.origin.clone()
