    const seat=new THREE.Mesh(seatGeo,mat);seat.castShadow=true;
    seat.position.copy(base.clone().addScaledVector(f.normal,normalOff+seatH/2));
    seat.quaternion.copy(q);group.add(seat);
    const back=new THREE.Mesh(backGeo,backMat);back.castShadow=true;
