function placeLsofa(face,aU,aV,lenA,lenB,variant){
  const cellArr=lsofaCells(aU,aV,lenA,lenB,variant);
  if(cellArr.some(({u,v})=>u<0||v<0||u>=SIZE||v>=SIZE))return null;
  const id=pieceCounter++;
  const color=COUCH_COLORS[pieces.filter(p=>p.type==='lsofa').length%COUCH_COLORS.length];
  const bb=bboxOf(cellArr);
  const group=buildLsofaMesh(face,cellArr,color,H_LSOFA,0);
  scene.add(group);group.userData.pieceId=id;
  const p={id,type:'lsofa',face,uMin:bb.uMin,vMin:bb.vMin,uMax:bb.uMax,vMax:bb.vMax,
           cells:cellArr,anchorU:aU,anchorV:aV,lenA,lenB,variant,color,label:'L-Sofa '+(id+1),mesh:group,height:H_LSOFA,floatDepth:0,opacity:1};
  pieces.push(p);stampCells(face,id,cellArr);return p;
}

const RUG_MAX=16;
function placeRug(face,cellArr){
  const id=pieceCounter++;rugCount++;
  const color=RUG_COLORS[(rugCount-1)%RUG_COLORS.length];
  const bb=bboxOf(cellArr);
  const f=FACES[face];
  const group=new THREE.Group();
  const geo=new THREE.BoxGeometry(CELL*0.9,H_RUG,CELL*0.9);
  const mat=new THREE.MeshLambertMaterial({color,transparent:true,opacity:0.85});
  const xA=f.uAxis.clone(),yA=f.normal.clone(),zA=f.vAxis.clone();
  const q=new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(xA,yA,zA));
  for(const{u,v}of cellArr){
    const m=new THREE.Mesh(geo,mat);m.receiveShadow=true;
    const ctr=f.origin.clone().addScaledVector(f.uAxis,(u+0.5)*CELL).addScaledVector(f.vAxis,(v+0.5)*CELL).addScaledVector(f.normal,H_RUG/2);
    m.position.copy(ctr);m.quaternion.copy(q);group.add(m);
  }
  scene.add(group);group.userData.pieceId=id;
  const p={id,type:'rug',face,uMin:bb.uMin,vMin:bb.vMin,uMax:bb.uMax,vMax:bb.vMax,
           cells:cellArr,color,label:'Rug '+rugCount,mesh:group,height:H_RUG,floatDepth:0,opacity:0.85};
