// ── Edge helper ───────────────────────────────────────────────
// Attaches a fully-opaque edge outline to `parent` using `geo`.
// Optional quaternion `q` lets the lines inherit the same rotation.
function addEdgeLines(parent,geo,edgeColor){
  const eMat=new THREE.LineBasicMaterial({color:edgeColor??0xffffff,transparent:false,opacity:1,depthTest:true});
  parent.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo),eMat));
}

// Conflict colour
function setMeshColor(obj,hex){
  // Update fill meshes
  obj.traverse(ch=>{if(ch.isMesh&&ch.material&&ch.material.color&&!ch.material.wireframe)ch.material.color.setHex(hex);});
  // Keep edge lines tinted with a lighter version of the same colour
  const edgeHex=liftColor(hex,0.55);
  obj.traverse(ch=>{if(ch.isLineSegments&&ch.material)ch.material.color.setHex(edgeHex);});
}

// Returns `hex` blended toward white by `t` (0=unchanged, 1=white)
function liftColor(hex,t){
  const r=((hex>>16)&0xff),g=((hex>>8)&0xff),b=(hex&0xff);
  const lr=Math.round(r+(255-r)*t),lg=Math.round(g+(255-g)*t),lb=Math.round(b+(255-b)*t);
  return(lr<<16)|(lg<<8)|lb;
}

