let selHighlight=null;
function updateSelHighlight(p){
  if(selHighlight){scene.remove(selHighlight);selHighlight=null;}
  if(!p)return;
  const f=FACES[p.face];
  const cols=(p.uMax-p.uMin+1),rows=(p.vMax-p.vMin+1);
  const w=cols*CELL,h=p.height,d=rows*CELL;
  const group=new THREE.Group();
  // Three shells: tight→loose, bright→faint
  const shells=[
    {scale:1.06, color:0xffffff, opacity:0.55},
    {scale:1.16, color:0xffffff, opacity:0.28},
