// Selection glow — multi-shell BackSide corona + sparkle particles
let selHighlight=null;

// Tiny bright-circle texture for sparkles
(function makeSparkTex(){
  const sz=32,c=document.createElement('canvas');
  c.width=c.height=sz;
  const ctx=c.getContext('2d');
  const g=ctx.createRadialGradient(sz/2,sz/2,0,sz/2,sz/2,sz/2);
  g.addColorStop(0,'rgba(255,255,255,1)');
  g.addColorStop(0.25,'rgba(220,240,255,0.85)');
  g.addColorStop(0.6,'rgba(160,200,255,0.3)');
  g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g;ctx.fillRect(0,0,sz,sz);
  window._sparkTex=new THREE.CanvasTexture(c);
})();

function updateSelHighlight(p){
  if(selHighlight){scene.remove(selHighlight);selHighlight=null;}
  if(!p)return;
  const f=FACES[p.face];
  const cols=(p.uMax-p.uMin+1),rows=(p.vMax-p.vMin+1);
  const w=cols*CELL,h=p.height,d=rows*CELL;
  const group=new THREE.Group();

  // ── Glow shells (BackSide coronas) ──────────────────────────
  const shells=[
    {scale:1.06, color:0xffffff, opacity:0.55},
    {scale:1.16, color:0xffffff, opacity:0.28},
    {scale:1.30, color:0xffffff, opacity:0.12},
  ];
  for(const s of shells){
    const geo=new THREE.BoxGeometry(w*s.scale,h*s.scale,d*s.scale);
    const mat=new THREE.MeshBasicMaterial({
      color:s.color,side:THREE.BackSide,
      transparent:true,opacity:s.opacity,depthWrite:false
    });
    group.add(new THREE.Mesh(geo,mat));
  }

  // ── Sparkle particle system ──────────────────────────────────
  const N=60; // particle count
  const positions=new Float32Array(N*3);
  const phases  =new Float32Array(N);   // per-particle sine phase
  const speeds  =new Float32Array(N);   // drift speed multiplier
  const lives   =new Float32Array(N);   // 0..1 normalised age
  const maxLife =new Float32Array(N);   // total lifetime in seconds
  const vels    =new Float32Array(N*3); // drift direction

  // Spawn one particle at a random point on the piece surface shell
  function spawnParticle(i){
    // Pick a random face of the bounding box, offset slightly outward
    const side=Math.floor(Math.random()*6);
    let px,py,pz;
    const hw=w/2,hh=h/2,hd=d/2;
    const spread=0.18; // how far beyond the surface to scatter
    if(side===0){px=(Math.random()-0.5)*w;  py=hh;               pz=(Math.random()-0.5)*d;}
    else if(side===1){px=(Math.random()-0.5)*w;  py=-hh;              pz=(Math.random()-0.5)*d;}
    else if(side===2){px=hw;               py=(Math.random()-0.5)*h;pz=(Math.random()-0.5)*d;}
    else if(side===3){px=-hw;              py=(Math.random()-0.5)*h;pz=(Math.random()-0.5)*d;}
    else if(side===4){px=(Math.random()-0.5)*w;  py=(Math.random()-0.5)*h;pz=hd;}
    else             {px=(Math.random()-0.5)*w;  py=(Math.random()-0.5)*h;pz=-hd;}
    // Jitter slightly off surface
    const jitter=0.12+Math.random()*spread;
    const len=Math.sqrt(px*px+py*py+pz*pz)||1;
    positions[i*3  ]=px+(px/len)*jitter;
    positions[i*3+1]=py+(py/len)*jitter;
    positions[i*3+2]=pz+(pz/len)*jitter;
    // Drift outward + slight random
    const spd=0.4+Math.random()*0.7;
    vels[i*3  ]=(px/len)*spd+(Math.random()-0.5)*0.3;
    vels[i*3+1]=(py/len)*spd+(Math.random()-0.5)*0.3+0.25;
    vels[i*3+2]=(pz/len)*spd+(Math.random()-0.5)*0.3;
    speeds[i]=spd;
    phases[i]=Math.random()*Math.PI*2;
    lives[i]=Math.random(); // stagger initial ages so they don't all pop at once
    maxLife[i]=0.6+Math.random()*0.8;
  }
  for(let i=0;i<N;i++)spawnParticle(i);

  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.BufferAttribute(positions,3));
  const mat=new THREE.PointsMaterial({
    map:window._sparkTex,
    size:0.55,sizeAttenuation:true,
    transparent:true,opacity:1,
    depthWrite:false,blending:THREE.AdditiveBlending,
    vertexColors:false,color:0xffffff
  });
  const points=new THREE.Points(geo,mat);
  points.userData={positions,phases,speeds,lives,maxLife,vels,N,spawnFn:spawnParticle};
  group.add(points); // index 3 in children

  // ── Position + orient group to match the piece ───────────────
  const centre=f.origin.clone()
    .addScaledVector(f.uAxis,(p.uMin+cols/2)*CELL)
    .addScaledVector(f.vAxis,(p.vMin+rows/2)*CELL)
    .addScaledVector(f.normal,(p.floatDepth||0)*CELL+h/2);
  group.position.copy(centre);
  group.setRotationFromMatrix(
    new THREE.Matrix4().makeBasis(f.uAxis.clone(),f.normal.clone(),f.vAxis.clone())
  );
  scene.add(group);
  selHighlight=group;
}

