function animate(){
  requestAnimationFrame(animate);
  if(selHighlight){
    const t=Date.now()*0.0035;
    const dt=1/60; // assume ~60fps for particle step

    // Pulse glow shells (children 0-2)
    const pulse=0.5+0.5*Math.sin(t);
    const baseOpacities=[0.55,0.28,0.12];
    for(let i=0;i<3;i++){
      selHighlight.children[i].material.opacity=baseOpacities[i]*(0.55+0.45*pulse);
    }

    // Tick sparkles (child 3)
    const pts=selHighlight.children[3];
    if(pts){
      const {positions,phases,lives,maxLife,vels,N,spawnFn}=pts.userData;
      for(let i=0;i<N;i++){
        lives[i]+=dt/maxLife[i];
        if(lives[i]>=1){spawnFn(i);lives[i]=0;continue;}
        // Drift position
        positions[i*3  ]+=vels[i*3  ]*dt;
        positions[i*3+1]+=vels[i*3+1]*dt;
        positions[i*3+2]+=vels[i*3+2]*dt;
        // Twinkle: size driven by per-particle sine + lifecycle bell curve
        phases[i]+=dt*8*(0.8+Math.random()*0.4);
      }
      pts.geometry.attributes.position.needsUpdate=true;
      // Overall sparkle opacity: twinkle the whole Points material
      pts.material.opacity=0.6+0.4*Math.sin(t*3.7+1.2);
      // Per-frame size variation for shimmer
      pts.material.size=0.45+0.2*Math.sin(t*5.1);
    }
  }
  renderer.render(scene,camera);
}

