  const cols=uMax-uMin+1,rows=vMax-vMin+1;
  const geo=new THREE.BoxGeometry(cols*CELL,height,rows*CELL);
  const mat=new THREE.MeshLambertMaterial({color:conflict?0xff4444:color,transparent:true,opacity:0.42});
  const mesh=new THREE.Mesh(geo,mat);
  mesh.castShadow=mesh.receiveShadow=true;
  const centre=f.origin.clone()
    .addScaledVector(f.uAxis,(uMin+cols/2)*CELL)
    .addScaledVector(f.vAxis,(vMin+rows/2)*CELL)
    .addScaledVector(f.normal,height/2);
  mesh.position.copy(centre);
  mesh.setRotationFromMatrix(new THREE.Matrix4().makeBasis(f.uAxis.clone(),f.normal.clone(),f.vAxis.clone()));
  scene.add(mesh);ghostMeshes.push(mesh);
}

