681 | function getPieceAt(e){
682 |   raycaster.setFromCamera(toNDC(e),camera);
683 |   const objs=[];
684 |   for(const p of pieces){
685 |     const tag=ch=>{if(ch.isMesh){ch._pid=p.id;objs.push(ch);}};
686 |     if(p.mesh instanceof THREE.Group)p.mesh.children.forEach(tag);
687 |     else{p.mesh._pid=p.id;objs.push(p.mesh);p.mesh.children.forEach(tag);}
688 |   }
689 |   const hits=raycaster.intersectObjects(objs);
690 |   if(!hits.length)return null;
691 |   let obj=hits[0].object;
692 |   while(obj&&obj._pid===undefined&&obj.userData.pieceId===undefined)obj=obj.parent;
693 |   const pid=obj?._pid??obj?.userData?.pieceId;
694 |   return pid!==undefined?pieces.find(p=>p.id===pid)||null:null;
695 | }
