// ── Merge mode state ─────────────────────────────────────────
let mergeMode=false,mergeAnchor=null;
const mergeHintEl=document.getElementById('merge-hint');

// Flatten any piece to a cell array [{u,v}]
function pieceToCells(p){
  if(p.cells)return p.cells.slice();
  const arr=[];
  for(let v=p.vMin;v<=p.vMax;v++)for(let u=p.uMin;u<=p.uMax;u++)arr.push({u,v});
  return arr;
}

// Two pieces can merge if they're on the same face with the same color
function canMerge(a,b){
  return a!==b && a.face===b.face && a.color===b.color;
}

// Returns true if the current face has at least one piece that can merge with p
function hasMergePartner(p){
  return pieces.some(q=>canMerge(p,q));
}

function enterMergeMode(p){
  mergeMode=true;mergeAnchor=p;
  mergeHintEl.style.display='block';
  btnMerge.classList.add('active');
  clearGhosts();
}
function exitMergeMode(){
  mergeMode=false;mergeAnchor=null;
  mergeHintEl.style.display='none';
  btnMerge.classList.remove('active');
  clearGhosts();
}

function placeMerged(face,cellArr,color,height){
  const id=pieceCounter++;
  const bb=bboxOf(cellArr);
  const f=FACES[face];
  const group=new THREE.Group();
  const geo=new THREE.BoxGeometry(CELL*0.95,height,CELL*0.95);
  const mat=new THREE.MeshLambertMaterial({color});
  const xA=f.uAxis.clone(),yA=f.normal.clone(),zA=f.vAxis.clone();
  const q=new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(xA,yA,zA));
  for(const{u,v}of cellArr){
    const m=new THREE.Mesh(geo,mat);m.castShadow=m.receiveShadow=true;
    const ctr=f.origin.clone()
      .addScaledVector(f.uAxis,(u+0.5)*CELL)
      .addScaledVector(f.vAxis,(v+0.5)*CELL)
      .addScaledVector(f.normal,height/2);
    m.position.copy(ctr);m.quaternion.copy(q);
    addEdgeLines(m,geo,liftColor(color,0.55));
    group.add(m);
  }
  scene.add(group);group.userData.pieceId=id;
  const p={id,type:'merged',face,uMin:bb.uMin,vMin:bb.vMin,uMax:bb.uMax,vMax:bb.vMax,
           cells:cellArr,color,label:'Merged '+(id+1),mesh:group,height,floatDepth:0};
  pieces.push(p);stampCells(face,id,cellArr);return p;
}

function doMerge(anchor,target){
  const color=anchor.color;
  const height=Math.max(anchor.height,target.height);
  const face=anchor.face;
  // Collect all cells from both pieces (deduplicate by u,v key)
  const seen=new Set();
  const allCells=[];
  for(const c of [...pieceToCells(anchor),...pieceToCells(target)]){
    const k=c.u+','+c.v;
    if(!seen.has(k)){seen.add(k);allCells.push(c);}
  }
  deletePiece(anchor);
  deletePiece(target);
  const merged=placeMerged(face,allCells,color,height);
  refreshAllColors();
  selectPiece(merged);
}

